			/*
			 * 인풋 박스에서 value-change 이벤트 발생 시 호출.
			 * 변경된 value가 저장된 후에 발생하는 이벤트.
			 */
			function onIpb90ValueChange(e) {
			    //    var ipb90 = e.control;
			    //ipb84 : 단독사용 개수
			    //ipb86 : 공동사용 개수
			    //ipb85 : 합계 개수
			    //ipb87 : 단독사용 면적
			    //ipb88 : 공동사용 면적
			    //ipb89 : 합계 면적
			    var ipb84 = 0;
			    var ipb86 = 0;
			    var ipb87 = 0;
			    var ipb88 = 0;
			    var grd3 = app.lookup('grd3');
			    var cnt = grd3.getDataRowCount();
			    for (var i = 0; i < cnt; i++) {
			        var data = grd3.getDataRow(i);
			        var SNGA_USE_YN = data.getValue('SNGA_USE_YN');
			        if (SNGA_USE_YN == 'Y') { //단독
			            ipb84 += (data.getValue('USE_SPCE_CUNT') - 0);
			            ipb87 += (data.getValue('USE_SPCE_AR_VALUE') - 0);
			        } else if (SNGA_USE_YN == 'N') { //공용
			            ipb86 += (data.getValue('USE_SPCE_CUNT') - 0);
			            ipb88 += (data.getValue('USE_SPCE_AR_VALUE') - 0);
			        }
			    }
			    app.lookup('ipb84').value = ipb84;
			    app.lookup('ipb86').value = ipb86;
			    app.lookup('ipb87').value = ipb87;
			    app.lookup('ipb88').value = ipb88;
			    app.lookup('ipb85').value = ipb84 + ipb86;
			    app.lookup('ipb89').value = ipb87 + ipb88;
			}

